export const createNotifications = catchAsync(async (req, res) => {
  const { body } = req;
  body.createdBy = req.user._id;
  body.updatedBy = req.user._id;
  const options = {};
  const notifications = await notificationsService.createNotifications(body, options);

  if (body.receiverId) {
    notificationService
      .sendNotificationToUser(body.receiverId, {
        title: body.title || 'Karyaah Notification',
        body: body.message || '',
        data: {
          notificationId: String(notifications._id),
          notificationType: body.notificationType || 'GENERAL',
          related: body.related ? String(body.related) : '',
        },
      })
      .catch(() => {});
  }

  return res.status(httpStatus.CREATED).send({ results: notifications });
});

export const updateNotifications = catchAsync(async (req, res) => {
  const { body } = req;
  body.updatedBy = req.user;
  const { notificationsId } = req.params;
  const filter = {
    _id: notificationsId,
  };
  const options = { new: true };
  const notifications = await notificationsService.updateNotifications(filter, body, options);
  return res.status(httpStatus.OK).send({ results: notifications });
});

